package bd.trend99.app;
import android.app.Activity;import android.os.Bundle;import android.widget.*;import org.json.*;import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;
public class MainActivity extends Activity {
 public interface Transport { String send(String path,JSONObject payload,String token)throws Exception; }
 public static volatile Transport testTransport;
 final ExecutorService executor=Executors.newSingleThreadExecutor();LinearLayout body;TextView notice;String token,user,business,retry;JSONObject product;int quantity;boolean busy;
 public void onCreate(Bundle state){super.onCreate(state);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(20,20,20,20);setContentView(root);TextView title=new TextView(this);title.setText("Trend99 BD · COD");title.setTextSize(24);root.addView(title);LinearLayout nav=new LinearLayout(this);root.addView(nav);button(nav,"Shop",()->shop());button(nav,"Account",()->account());button(nav,"Cart",()->checkout());button(nav,"Orders",()->orders());notice=new TextView(this);root.addView(notice);ScrollView scroll=new ScrollView(this);root.addView(scroll);body=new LinearLayout(this);body.setOrientation(1);scroll.addView(body);shop();}
 interface Action{void run()throws Exception;}interface Result{void accept(String s)throws Exception;}
 void button(LinearLayout parent,String label,Action action){Button b=new Button(this);b.setText(label);parent.addView(b);b.setOnClickListener(v->{if(busy)return;try{action.run();}catch(Exception e){notice.setText(e.getMessage());}});}
 void text(String value){TextView t=new TextView(this);t.setText(value);t.setTextSize(18);body.addView(t);}void clear(){body.removeAllViews();notice.setText("");}
 EditText field(String hint,boolean secret){EditText e=new EditText(this);e.setHint(hint);e.setSingleLine(true);if(secret)e.setInputType(129);body.addView(e);return e;}String money(long n){return String.format(Locale.US,"BDT %.2f",n/100.0);}
 String send(String path,JSONObject payload)throws Exception{Transport fake=testTransport;if(fake!=null)return fake.send(path,payload,token);HttpURLConnection c=(HttpURLConnection)new URL("https://eytzancbmgipdsehsnni.supabase.co"+path).openConnection();try{c.setConnectTimeout(15000);c.setReadTimeout(20000);c.setRequestProperty("apikey","sb_publishable_v151wbmbu9aTkoJPt-uObQ_9VXym-dv");if(token!=null)c.setRequestProperty("Authorization","Bearer "+token);if(payload!=null){c.setRequestMethod("POST");c.setRequestProperty("Content-Type","application/json");c.setDoOutput(true);try(OutputStream o=c.getOutputStream()){o.write(payload.toString().getBytes(StandardCharsets.UTF_8));}}int status=c.getResponseCode();InputStream stream=status<400?c.getInputStream():c.getErrorStream();StringBuilder out=new StringBuilder();if(stream!=null)try(BufferedReader r=new BufferedReader(new InputStreamReader(stream,StandardCharsets.UTF_8))){String line;while((line=r.readLine())!=null)out.append(line);}if(status>=400){String error="HTTP "+status;try{JSONObject o=new JSONObject(out.toString());error=o.optString("msg",o.optString("message",o.optString("error_description",error)));}catch(Exception ignored){}throw new Exception(error);}return out.toString();}finally{c.disconnect();}}
 void call(String path,JSONObject payload,Result result){busy=true;notice.setText("Loading");executor.execute(()->{try{String s=send(path,payload);runOnUiThread(()->{busy=false;notice.setText("");try{result.accept(s);}catch(Exception e){notice.setText(e.getMessage());}});}catch(Exception e){runOnUiThread(()->{busy=false;notice.setText(e.getMessage());});}});}
 void shop(){clear();call("/rest/v1/products?select=*&published=eq.true&limit=100",null,s->{JSONArray a=new JSONArray(s);if(a.length()==0)text("No published products");for(int i=0;i<a.length();i++){JSONObject p=a.getJSONObject(i);text(p.getString("name_bn")+" / "+p.getString("name_en")+" · "+money(p.getLong("price_paisa"))+" · Stock "+p.getInt("stock"));button(body,"Add: "+p.getString("name_en"),()->{if(product!=null&&!product.getString("id").equals(p.getString("id")))throw new Exception("Preview supports one product per cart");if(quantity>=p.getInt("stock"))throw new Exception("Insufficient stock");product=p;business=p.getString("business_id");quantity++;retry=null;notice.setText("Added to cart");});}});}
 void account(){clear();if(token!=null){text("Signed in");button(body,"Sign out",()->{token=null;user=null;product=null;quantity=0;retry=null;account();});return;}EditText email=field("Email",false),password=field("Password",true);button(body,"Sign in",()->call("/auth/v1/token?grant_type=password",new JSONObject().put("email",email.getText().toString().trim()).put("password",password.getText().toString()),s->{JSONObject o=new JSONObject(s);token=o.getString("access_token");user=o.getJSONObject("user").getString("id");clear();text("Signed in");}));button(body,"Create account",()->call("/auth/v1/signup",new JSONObject().put("email",email.getText().toString().trim()).put("password",password.getText().toString()),s->notice.setText("Check email if confirmation is required, then sign in")));}
 void checkout(){clear();if(product==null||quantity==0){text("Cart is empty");return;}if(token==null){text("Sign in before checkout");return;}call("/rest/v1/delivery_rates?select=*&business_id=eq."+business,null,s->{JSONArray rates=new JSONArray(s);if(rates.length()==0){text("Delivery is not configured");return;}Spinner district=new Spinner(this);ArrayList<String> names=new ArrayList<>();for(int i=0;i<rates.length();i++)names.add(rates.getJSONObject(i).getString("district"));district.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,names));body.addView(district);TextView total=new TextView(this);body.addView(total);district.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> a){}public void onItemSelected(AdapterView<?> a,android.view.View v,int pos,long id){try{total.setText("Estimated total: "+money(product.getLong("price_paisa")*quantity+rates.getJSONObject(pos).getLong("delivery_paisa")));}catch(Exception e){notice.setText(e.getMessage());}}});EditText name=field("Full name",false),phone=field("Mobile",false),area=field("Area",false),address=field("Address",false);button(body,"Place COD order",()->{if(retry==null)retry=UUID.randomUUID().toString();JSONObject p=new JSONObject().put("p_business",business).put("p_name",name.getText().toString()).put("p_phone",phone.getText().toString()).put("p_district",names.get(district.getSelectedItemPosition())).put("p_area",area.getText().toString()).put("p_address",address.getText().toString()).put("p_items",new JSONArray().put(new JSONObject().put("product_id",product.getString("id")).put("quantity",quantity))).put("p_key",retry);call("/rest/v1/rpc/place_cod_order",p,result->{product=null;quantity=0;retry=null;clear();text("COD order received: "+result);});});});}
 void orders(){clear();if(token==null){text("Sign in to view orders");return;}call("/rest/v1/orders?select=id,status&customer_id=eq."+user+"&limit=100",null,s->{JSONArray a=new JSONArray(s);for(int i=0;i<a.length();i++)text(a.getJSONObject(i).toString());});}
 protected void onDestroy(){executor.shutdownNow();super.onDestroy();}
}
